package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.Locale;
@Entity @Table(name="evidence_pillar",uniqueConstraints={@UniqueConstraint(name="uk_evidence_pillar_code",columnNames={"agency_id","framework_version_id","normalized_code"}),@UniqueConstraint(name="uk_evidence_pillar_order",columnNames={"agency_id","framework_version_id","display_order"})})
public class EvidencePillar extends RspAuditedEntity{@Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=200)private String title;@Column(length=2000)private String description;@Column(name="display_order",nullable=false)private int displayOrder;protected EvidencePillar(){}public EvidencePillar(String agency,String framework,String code,String title,String description,int order){super(agency);frameworkVersionId=requiredText(framework,"frameworkVersionId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.title=requiredText(title,"title");this.description=optionalText(description);if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getFrameworkVersionId(){return frameworkVersionId;}public String getCode(){return code;}public String getTitle(){return title;}public String getDescription(){return description;}public int getDisplayOrder(){return displayOrder;}}
